/* 2026-08-23 P115：本地设备控制命令识别（音量/亮度）。
 * ASR 文本命中关键词 → 短路 LLM：填 cmd_out（如 "volume:-5" / "brightness:+5"）
 * 返回 1；否则返回 0 走正常 LLM 链路。中文关键词匹配，无外部依赖。
 * 步长默认 5（用户需求：说"声音小一点"→ 音量减小 5%）。 */
static int voice_local_cmd_parse(const char *text, char *cmd_out, size_t cap)
{
    if (!text || !text[0] || !cmd_out || cap < 16)
        return 0;

    int is_vol = (strstr(text, "音量") || strstr(text, "声音"));
    int is_bri = (strstr(text, "亮度") || strstr(text, "背光"));
    if (!is_vol && !is_bri)
        return 0;

    /* 方向：先查负向（小/低/暗/减/降），再查正向（大/高/亮/加/增）。
     * 顺序关键："亮度调暗" 同时含"亮"（亮度自身）与"暗"，负向优先。 */
    int dir = 0;
    if (strstr(text, "小") || strstr(text, "低") || strstr(text, "暗") ||
        strstr(text, "减") || strstr(text, "降"))
        dir = -1;
    else if (strstr(text, "大") || strstr(text, "高") || strstr(text, "亮") ||
             strstr(text, "加") || strstr(text, "增"))
        dir = 1;
    if (dir == 0)
        return 0;

    int step = 5;
    snprintf(cmd_out, cap, "%s:%+d",
             is_vol ? "volume" : "brightness", dir * step);
    return 1;
}

