static int cn_digit(const char *s)
{
    static const struct { const char *w; int v; } tab[] = {
        { "零", 0 }, { "一", 1 }, { "二", 2 }, { "两", 2 }, { "三", 3 },
        { "四", 4 }, { "五", 5 }, { "六", 6 }, { "七", 7 }, { "八", 8 },
        { "九", 9 }, { "十", 10 }, { NULL, 0 }
    };
    for (int i = 0; tab[i].w; i++)
        if (strncmp(s, tab[i].w, 3) == 0)
            return tab[i].v;
    return -1;
}

/* 解析中文/阿拉伯数字 0-100：s 指向数字起点，返回解析值或 -1 */
static int cn_parse_num(const char *s)
{
    if (!s) return -1;
    if (s[0] >= '0' && s[0] <= '9') {
        int v = 0;
        while (*s >= '0' && *s <= '9') { v = v * 10 + (*s - '0'); s++; }
        return v > 100 ? -1 : v;
    }
    /* 中文：支持 0-100 */
    if (strncmp(s, "一百", 6) == 0) return 100;
    int d1 = cn_digit(s);
    if (d1 < 0) return -1;
    if (d1 == 10) {  /* 十X */
        int d2 = cn_digit(s + 3);
        return d2 > 0 && d2 < 10 ? 10 + d2 : 10;
    }
    /* 数字 后跟 十 → 几十 */
    if (d1 >= 1 && d1 <= 9) {
        const char *n = s + 3;
        if (strncmp(n, "十", 3) == 0) {
            int d2 = cn_digit(n + 3);
            if (d2 > 0 && d2 < 10) return d1 * 10 + d2;
            return d1 * 10;
        }
        return d1;
    }
    return d1;  /* 零 */
}
