static int cn_digit(const char *s)  /* 返回 0-9 或 -1 */
{
    static const char *t[] = {"零","一","二","三","四","五","六","七","八","九"};
    for (int i = 0; i < 10; i++)
        if (strncmp(s, t[i], 3) == 0) return i;
    return -1;
}

static int cn_num(const char *s, int *out)
