```c
static int voice_local_cmd_parse(const char *text, char *cmd_out, size_t cap)
{
    if (!text || !text[0] || !cmd_out || cap < 16)
        return 0;

    /* ── 音乐控制（先于音量/亮度判断，避免"播放"等词误入）── */
    if (strstr(text, "播放") || strstr(text, "继续") || strstr(text, "放音乐") ||
        strstr(text, "来一首") || strstr(text, "唱一首"))
        { snprintf(cmd_out, cap, "music:play"); return 1; }
    if (strstr(text, "暂停") || strstr(text, "停一下") || strstr(text, "别放"))
        { snprintf(cmd_out, cap, "music:pause"); return 1; }
    if (strstr(text, "下一曲") || strstr(text, "下一首") || strstr(text, "切歌") ||
        strstr(text, "换一首") || strstr(text, "换歌"))
        { snprintf(cmd_out, cap, "music:next"); return 1; }
    if (strstr(text, "上一曲") || strstr(text, "上一首"))
        { snprintf(cmd_out, cap, "music:prev"); return 1; }

    /* ── 音量 / 亮度 ── */
    int is_vol = (strstr(text, "音量") || strstr(text, "声音"));
    int is_bri = (strstr(text, "亮度") || strstr(text, "背光"));
    if (!is_vol && !is_bri)
        return 0;
    const char *dev = is_vol ? "volume" : "brightness";

    /* 绝对设置："调到 50" / "百分之五十" / "50%" / "调成 80" */
    int absval = -1;
    {
        /* 找数字起始位置（阿拉伯或中文） */
        const char *pct = strstr(text, "百分之");
        const char *to = strstr(text, "调到");
        if (!to) to = strstr(text, "调成");
        if (!to) to = strstr(text, "调为");
        const char *num = NULL;
        if (pct) num = pct + 3 * 3;   /* "百分之" = 3 个汉字 = 9 字节 */
        else if (to) num = to + 3 * 2; /* "调到" = 2 个汉字 = 6 字节 */
        else
            {
                const char *pct2 = strchr(text, '%');
                if (pct2 && pct2 > text) { /* 阿拉伯数字在 % 前 */
                    const char *q = pct2 - 1;
                    while (q >= text && *q >= '0' && *q <= '9') q--;
                    num = q + 1;
                }
            }
        if (num)
            {
                if (*num >= '0' && *num <= '9')
                    {
                        int v = atoi(num);
                        if (v >= 0 && v <= 100) absval = v;
                    }
                else if (cn_num(num, &absval) == 0 && absval > 100)
                    absval = -1;
            }
    }
    if (absval >= 0)
        { snprintf(cmd_out, cap, "%s:%d", dev, absval); return 1; }

    /* 相对步进 ±5（P115 保留） */
    int dir = 0;
    if (strstr(text, "小") || strstr(text, "低") || strstr(text, "暗") ||
        strstr(text, "减") || strstr(text, "降"))
        dir = -1;
    else if (strstr(text, "大") || strstr(text, "高") || strstr(text, "亮") ||
             strstr(text, "加") || strstr(text, "增"))
        dir = 1;
    if (dir == 0)
        return 0;

    snprintf(cmd_out, cap, "%s:%+d", dev, dir * 5);
    return 1;
}
```

