    /* 2026-08-23 P115/P116：消费本地设备控制命令（音乐/音量/亮度）。
     * agent 侧 ASR 命中关键词已短路 LLM 并广播 cmd 事件（"music:play" /
     * "volume:50" 绝对 / "volume:-5" 相对 / "brightness:+5"）；
     * 此处执行硬件（音乐播放控制/软件音量/背光 PWM）+ TTS 播报确认。 */
    {
        static char evt_cmd[64];
        if (dm_ai_voice_evt_cmd_poll(evt_cmd, sizeof(evt_cmd)))
            {
                char ack[64];
                /* ── 音乐控制 ── */
                if (strncmp(evt_cmd, "music:", 6) == 0)
                    {
                        const char *op = evt_cmd + 6;
                        if (strcmp(op, "play") == 0)
                            {
                                if (music_playing)
                                    snprintf(ack, sizeof(ack), "正在播放中");
                                else if (music_inited)
                                    {
                                        music_resume();
                                        snprintf(ack, sizeof(ack), "好的，继续播放");
                                    }
                                else
                                    {
                                        music_play(0);   /* 补扫曲库 + 恢复上次/第一首 */
                                        snprintf(ack, sizeof(ack), "好的，开始播放");
                                    }
                            }
                        else if (strcmp(op, "pause") == 0)
                            {
                                music_pause();
                                snprintf(ack, sizeof(ack), "好的，已暂停播放");
                            }
                        else if (strcmp(op, "next") == 0)
                            {
                                music_album_next(true);
                                snprintf(ack, sizeof(ack), "好的，下一曲");
                            }
                        else if (strcmp(op, "prev") == 0)
                            {
                                music_album_next(false);
                                snprintf(ack, sizeof(ack), "好的，上一曲");
                            }
                        else
                            snprintf(ack, sizeof(ack), "好的");
                        printf("[voice-cmd] music:%s\n", op);
                        dm_ai_voice_speak(ack);
                    }
                /* ── 音量：绝对（volume:50）或相对（volume:+5/-5）── */
                else if (strncmp(evt_cmd, "volume:", 7) == 0)
                    {
                        const char *val = evt_cmd + 7;
                        int n = atoi(val);
                        if (*val == '+' || *val == '-')
                            g_music_volume += n;   /* 相对步进 */
                        else
                            g_music_volume = n;    /* 绝对设置 */
                        if (g_music_volume < 0) g_music_volume = 0;
                        if (g_music_volume > 100) g_music_volume = 100;
                        if (music_vol_lbl)
                            lv_label_set_text_fmt(music_vol_lbl, "%d",
                                                  g_music_volume);
                        printf("[voice-cmd] volume=%d\n", g_music_volume);
                        snprintf(ack, sizeof(ack), "好的，音量已调到 %d%%",
                                 g_music_volume);
                        dm_ai_voice_speak(ack);
                    }
                /* ── 亮度：绝对（brightness:50）或相对（brightness:+5/-5）── */
                else if (strncmp(evt_cmd, "brightness:", 11) == 0)
                    {
                        const char *val = evt_cmd + 11;
                        int n = atoi(val);
                        if (*val == '+' || *val == '-')
                            g_screen_brightness += n;
                        else
                            g_screen_brightness = n;
                        if (g_screen_brightness < 0) g_screen_brightness = 0;
                        if (g_screen_brightness > 100) g_screen_brightness = 100;
                        {
                            int v = g_screen_brightness;
#ifdef CONFIG_LUNCHER_DM_APP
                            struct pwm_config pcfg;
                            memset(&pcfg, 0, sizeof(pcfg));
                            pcfg.period_ns  = 25000;               /* 40KHz */
                            pcfg.duty_ns    = (uint32_t)(25000u * v / 100);
                            pcfg.polarity   = PWM_POLARITY_NORMAL;  /* 与 settings 一致 */
                            hal_pwm_control(4, &pcfg);              /* 屏幕背光 PWM ch4 */
#endif
                        }
                        printf("[voice-cmd] brightness=%d\n",
                               g_screen_brightness);
                        snprintf(ack, sizeof(ack), "好的，亮度已调到 %d%%",
                                 g_screen_brightness);
                        dm_ai_voice_speak(ack);
                    }
            }
    }

